// ui_kits/app/links.js
try { (() => {
// Pedagogical identifiers + navigation service for the demo. Mirrors docs/CONTRATOS-NAVEGACAO.md.
// Only links that exist in the demo data are declared; everything else resolves to { ok:false, reason } — never to another item.
(() => {
  const D = window.QB_DATA,
    E = window.QB_EDITAL,
    P = window.QB_PLAN;
  const LINKS = {
    maps: {
      'dc-2a': {
        mapId: 'mm-dc-2a',
        title: 'Processo legislativo',
        rootNodeId: 'pl'
      }
    },
    decks: {
      'dc-2a': {
        deckId: 'deck-dc-2a'
      }
    },
    questionTopic: Object.fromEntries(D.questions.map(q => [q.id, 'dc-2a'])),
    nodeTopic: Object.fromEntries(D.mapNodes.map(n => [n.id, 'dc-2a'])),
    flashcardTopic: 'dc-2a'
  };
  const pendingByTopic = {};
  Object.values(P.weeks).flat().forEach(t => {
    if (t.status === 'done' || !t.topicNum || t.date > P.today) return;
    const id = t.subjectId + '-' + t.topicNum;
    pendingByTopic[id] = (pendingByTopic[id] || 0) + 1;
  });
  const find = (subjectId, topicId) => {
    const s = E.subjects.find(x => x.id === subjectId);
    return {
      s,
      t: s && s.topics.find(x => x.id === topicId)
    };
  };
  const REASONS = {
    'topic-not-found': 'O identificador de matéria ou assunto não existe no edital carregado.',
    'no-questions': 'Não há questões vinculadas a este assunto na base de demonstração.',
    'no-map': 'Não há mapa mental vinculado a este assunto na base de demonstração.',
    'node-not-found': 'O nó solicitado não existe no mapa deste assunto.',
    'no-deck': 'Não há revisão ativa (flashcards) vinculada a este assunto na base de demonstração.',
    'no-node-questions': 'Nenhuma questão está vinculada a este nó.',
    'question-not-found': 'A questão solicitada não existe na base vinculada a este assunto.',
    'unknown-action': 'Ação sem destino definido.'
  };
  function resolve(i) {
    const {
      s,
      t
    } = find(i.subjectId, i.topicId);
    if (!s || !t) return {
      ok: false,
      reason: 'topic-not-found'
    };
    if (i.action === 'architect') return {
      ok: true,
      view: 'architect'
    };
    if (i.action === 'train') {
      const n = D.questions.filter(q => LINKS.questionTopic[q.id] === t.id).length;
      return n ? {
        ok: true,
        view: 'questions',
        note: n + ' questões'
      } : {
        ok: false,
        reason: 'no-questions'
      };
    }
    if (i.action === 'review') {
      const n = LINKS.decks[t.id] ? D.flashcards.length : 0;
      return n ? {
        ok: true,
        view: 'flashcards',
        note: n + ' cartões'
      } : {
        ok: false,
        reason: 'no-deck'
      };
    }
    if (i.action === 'mindmap') {
      const m = LINKS.maps[t.id];
      if (!m) return {
        ok: false,
        reason: 'no-map'
      };
      if (i.nodeId && !D.mapNodes.some(n => n.id === i.nodeId && LINKS.nodeTopic[n.id] === t.id)) return {
        ok: false,
        reason: 'node-not-found'
      };
      return {
        ok: true,
        view: 'map',
        mapId: m.mapId,
        nodeId: i.nodeId || m.rootNodeId,
        note: '1 mapa'
      };
    }
    if (i.action === 'node-questions') {
      const idx = D.questions.findIndex(q => q.node === i.nodeId);
      return idx < 0 ? {
        ok: false,
        reason: 'no-node-questions'
      } : {
        ok: true,
        view: 'questions',
        questionIndex: idx,
        questionId: D.questions[idx].id
      };
    }
    if (i.action === 'question') {
      const idx = D.questions.findIndex(q => q.id === i.questionId && LINKS.questionTopic[q.id] === t.id);
      return idx < 0 ? {
        ok: false,
        reason: 'question-not-found'
      } : {
        ok: true,
        view: 'questions',
        questionIndex: idx,
        questionId: i.questionId
      };
    }
    return {
      ok: false,
      reason: 'unknown-action'
    };
  }
  const topicLabel = (subjectId, topicId) => {
    const {
      s,
      t
    } = find(subjectId, topicId);
    return s && t ? s.short + ' ' + t.num + (t.title ? ' — ' + t.title : '') : null;
  };
  window.QB_LINKS = LINKS;
  window.QB_NAV = {
    resolve,
    find,
    topicLabel,
    pendingByTopic,
    reasons: REASONS,
    mapCounts: Object.fromEntries(Object.keys(LINKS.maps).map(k => [k, 1]))
  };
})();
})(); } catch (e) { __ds_ns.__errors.push({ path: "ui_kits/app/links.js", error: String((e && e.message) || e) }); }

// ui_kits/app/metrics.js
try { (() => {
// Shared metric definitions for the UI kit (single source so every screen agrees).
(() => {
  const topicsOf = s => s.topics;
  function totals(subjects) {
    let c = 0,
      w = 0,
      b = 0,
      studied = 0,
      total = 0;
    subjects.forEach(s => topicsOf(s).forEach(t => {
      c += t.correct;
      w += t.wrong;
      b += t.blank || 0;
      total++;
      if (t.status !== 'not-started') studied++;
    }));
    return {
      correct: c,
      wrong: w,
      blank: b,
      valid: c + w,
      answered: c + w + b,
      accuracy: c + w ? c / (c + w) * 100 : null,
      studied,
      total,
      coverage: studied / total * 100
    };
  }
  const pct = v => v == null ? '—' : Math.round(v) + '%';
  const dayStats = d => ({
    ...d,
    valid: d.correct + d.wrong,
    accuracy: d.correct + d.wrong ? d.correct / (d.correct + d.wrong) * 100 : null,
    net: d.correct - d.wrong
  });
  const fmtDate = iso => iso.slice(8, 10) + '/' + iso.slice(5, 7);
  window.QB_METRICS = {
    totals,
    pct,
    dayStats,
    fmtDate
  };
})();
})(); } catch (e) { __ds_ns.__errors.push({ path: "ui_kits/app/metrics.js", error: String((e && e.message) || e) }); }

// ui_kits/app/perf.js
try { (() => {
// Calculated metrics for Desempenho — pure functions over the answer log. Mirrors docs/DESEMPENHO-V4.md (PerformanceService).
// Scope = { from, to, subjectId | 'all', topicId | 'all' } with ISO dates. Presentation never computes metrics on its own.
(() => {
  const E = window.QB_EDITAL,
    P = window.QB_PLAN,
    PF = window.QB_PERF,
    NAV = window.QB_NAV;
  const RULES = {
    chartMinSample: 10,
    tableMinSample: 20,
    lowAccuracy: 60,
    recurringErrors: 5,
    recurringDays: 2
  };
  const WD = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'],
    MON = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
  const addDays = P.addDays;
  const fmt = iso => iso.slice(8, 10) + '/' + iso.slice(5, 7);
  const fmtFull = iso => fmt(iso) + '/' + iso.slice(0, 4);
  const fmtLong = iso => WD[new Date(iso + 'T12:00:00Z').getUTCDay()] + ', ' + fmtFull(iso);
  const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);
  const bounds = {
    min: PF.days[0].date,
    max: P.today
  };
  const sum = rows => {
    const a = {
      correct: 0,
      wrong: 0,
      blank: 0
    };
    rows.forEach(r => {
      a.correct += r.correct;
      a.wrong += r.wrong;
      a.blank += r.blank || 0;
    });
    a.valid = a.correct + a.wrong;
    a.n = a.valid + a.blank;
    a.accuracy = a.valid ? a.correct / a.valid * 100 : null;
    a.net = a.correct - a.wrong;
    return a;
  };
  const inScope = (sc, r) => (sc.subjectId === 'all' || r.subjectId === sc.subjectId) && (sc.topicId === 'all' || r.topicId === sc.topicId);
  const rows = sc => PF.log.filter(r => r.date >= sc.from && r.date <= sc.to && inScope(sc, r));
  const length = sc => Math.round((Date.parse(sc.to) - Date.parse(sc.from)) / 864e5) + 1;
  // Equal-length period immediately before; null when it would start before the first record (no base → no comparison).
  const previousScope = sc => {
    const from = addDays(sc.from, -length(sc));
    return from < bounds.min ? null : {
      ...sc,
      from,
      to: addDays(sc.from, -1)
    };
  };
  const bucketKey = (iso, g) => g === 'day' ? iso : g === 'month' ? iso.slice(0, 7) : addDays(iso, -new Date(iso + 'T12:00:00Z').getUTCDay());
  function series(sc, g) {
    const out = [],
      map = {};
    for (let d = sc.from; d <= sc.to; d = addDays(d, 1)) {
      const k = bucketKey(d, g);
      if (!map[k]) {
        map[k] = {
          key: k,
          from: d,
          to: d,
          rows: []
        };
        out.push(map[k]);
      }
      map[k].to = d;
    }
    rows(sc).forEach(r => map[bucketKey(r.date, g)].rows.push(r));
    return out.map(b => ({
      key: b.key,
      label: g === 'day' ? fmt(b.from) : g === 'month' ? MON[+b.key.slice(5) - 1] + '/' + b.key.slice(2, 4) : fmt(b.from) + '–' + fmt(b.to),
      longLabel: g === 'day' ? fmtLong(b.from) : fmtFull(b.from) + ' a ' + fmtFull(b.to),
      ...sum(b.rows)
    }));
  }
  const actionsFor = (subjectId, topicId) => ['train', 'mindmap', 'review', 'architect'].filter(a => NAV.resolve({
    action: a,
    subjectId,
    topicId
  }).ok);
  const groupOf = num => {
    const m = /^(\d+)/.exec(num);
    return m ? m[1] : num;
  };
  function tree(sc) {
    const by = {};
    rows(sc).forEach(r => (by[r.topicId] = by[r.topicId] || []).push(r));
    return E.subjects.filter(s => sc.subjectId === 'all' || s.id === sc.subjectId).map(s => {
      const topics = s.topics.filter(t => sc.topicId === 'all' || t.id === sc.topicId).map(t => ({
        id: t.id,
        level: 'topic',
        code: t.num,
        name: t.title || 'Título não disponível nos arquivos',
        untitled: !t.title,
        subjectId: s.id,
        topicId: t.id,
        actions: actionsFor(s.id, t.id),
        ...sum(by[t.id] || [])
      }));
      const groups = [],
        gm = {};
      topics.forEach(t => {
        const g = groupOf(t.code);
        if (!gm[g]) {
          gm[g] = {
            key: g,
            items: []
          };
          groups.push(gm[g]);
        }
        gm[g].items.push(t);
      });
      const children = groups.map(g => g.items.length === 1 ? g.items[0] : {
        id: s.id + ':' + g.key,
        level: 'group',
        code: g.key,
        name: E.groupTitles[s.id + ':' + g.key] || 'Título não disponível nos arquivos',
        untitled: !E.groupTitles[s.id + ':' + g.key],
        subjectId: s.id,
        children: g.items,
        ...sum(g.items)
      });
      return {
        id: s.id,
        level: 'subject',
        name: s.name,
        code: s.short,
        icon: s.icon,
        subjectId: s.id,
        children,
        ...sum(topics)
      };
    });
  }
  const allTasks = Object.values(P.weeks).flat();
  const taskInScope = (sc, t) => (sc.subjectId === 'all' || t.subjectId === sc.subjectId) && (sc.topicId === 'all' || t.subjectId + '-' + t.topicNum === sc.topicId);
  const tasks = sc => allTasks.filter(t => t.date >= sc.from && t.date <= sc.to && taskInScope(sc, t));
  // Demo has flashcard evaluations only for today's DC 2a deck.
  const flashcards = sc => sc.from <= P.today && sc.to >= P.today && (sc.subjectId === 'all' || sc.subjectId === 'dc') && (sc.topicId === 'all' || sc.topicId === window.QB_LINKS.flashcardTopic) ? PF.today.flashcards : null;
  const answers = sc => PF.answers.filter(a => a.date >= sc.from && a.date <= sc.to && inScope(sc, a));
  function priorities(sc) {
    const out = [],
      by = {};
    rows(sc).forEach(r => {
      const a = by[r.topicId] = by[r.topicId] || {
        subjectId: r.subjectId,
        topicId: r.topicId,
        rows: [],
        errDays: 0
      };
      a.rows.push(r);
      if (r.wrong) a.errDays++;
    });
    const T = Object.values(by).map(a => ({
      ...a,
      ...sum(a.rows),
      label: NAV.topicLabel(a.subjectId, a.topicId)
    }));
    const act = t => NAV.resolve({
      action: 'train',
      subjectId: t.subjectId,
      topicId: t.topicId
    }).ok ? {
      label: 'Treinar erros',
      icon: 'target',
      intent: {
        action: 'train',
        subjectId: t.subjectId,
        topicId: t.topicId
      }
    } : {
      label: 'Abrir assunto',
      icon: 'chevrons-down',
      open: {
        subjectId: t.subjectId,
        topicId: t.topicId
      }
    };
    const rec = T.filter(t => t.errDays >= RULES.recurringDays && t.wrong >= RULES.recurringErrors).sort((a, b) => b.wrong - a.wrong).slice(0, 2);
    rec.forEach(t => out.push({
      id: 'rec-' + t.topicId,
      kind: 'Erros recorrentes',
      tone: 'incorrect',
      title: t.label,
      reason: plural(t.wrong, 'erro', 'erros') + ' em ' + plural(t.errDays, 'dia', 'dias') + ' do período · ' + t.correct + ' de ' + plural(t.valid, 'resposta válida correta', 'respostas válidas corretas'),
      action: act(t)
    }));
    T.filter(t => t.valid >= RULES.tableMinSample && t.accuracy < RULES.lowAccuracy && !rec.includes(t)).sort((a, b) => a.accuracy - b.accuracy).slice(0, 2).forEach(t => out.push({
      id: 'low-' + t.topicId,
      kind: 'Baixa precisão',
      tone: 'incorrect',
      title: t.label,
      reason: Math.round(t.accuracy) + '% de acerto em ' + plural(t.valid, 'resposta válida', 'respostas válidas') + ' (amostra mínima: ' + RULES.tableMinSample + ')',
      action: act(t)
    }));
    const late = allTasks.filter(t => t.status === 'late' && t.date <= sc.to && taskInScope(sc, t));
    if (late.length) out.push({
      id: 'late',
      kind: 'Pendências vencidas',
      tone: 'attention',
      title: plural(late.length, 'tarefa vencida', 'tarefas vencidas'),
      reason: (late.length === 1 ? 'Planejada' : 'Planejadas') + ' até ' + fmt(sc.to) + ' e não ' + (late.length === 1 ? 'concluída' : 'concluídas') + ' · ' + plural(new Set(late.map(t => t.subjectId)).size, 'matéria', 'matérias'),
      action: {
        label: 'Reorganizar planejamento',
        icon: 'calendar-clock',
        go: ['plan', 'semana']
      }
    });
    const rev = allTasks.filter(t => t.type === 'revisao' && t.status === 'pending' && t.date === sc.to && taskInScope(sc, t));
    if (rev.length) {
      const auto = rev.filter(t => t.auto).length;
      out.push({
        id: 'rev',
        kind: 'Revisões necessárias',
        tone: 'gold',
        title: plural(rev.length, 'revisão agendada', 'revisões agendadas') + ' para ' + fmt(sc.to),
        reason: 'Ainda não ' + (rev.length === 1 ? 'concluída' : 'concluídas') + ' no planejamento' + (auto ? ' · ' + plural(auto, 'gerada automaticamente', 'geradas automaticamente') : ''),
        action: {
          label: 'Abrir planejamento do dia',
          icon: 'calendar',
          go: ['plan', 'hoje']
        }
      });
    }
    return out;
  }
  window.QB_PERF_CALC = {
    RULES,
    bounds,
    addDays,
    fmt,
    fmtFull,
    fmtLong,
    plural,
    sum,
    rows,
    length,
    previousScope,
    series,
    tree,
    tasks,
    flashcards,
    answers,
    priorities
  };
})();
})(); } catch (e) { __ds_ns.__errors.push({ path: "ui_kits/app/perf.js", error: String((e && e.message) || e) }); }

